std::vector<Node> nodes;
for (auto it = rt.finite_vertices_begin(); it != rt.finite_vertices_end(); ++it) {
    Node node;
    node.position = it->point();
    node.velocity = velocity(it);
    node.mass = it->info();
    int edge_count = 0;
    for (auto e = rt.vertex(it)->edges_begin(); e != rt.vertex(it)->edges_end(); ++e) {
        if (is_small_edge(rt, *e, threshold)) {
            edge_count++;
        }
    }
    node.type = type_from_edge_count(edge_count);
    nodes.push_back(node);
}
return nodes;

